profiles.imported_template:
TEMPLATE """{{ $has_head := true }}
{{ if .System }}<|startoftext|>{{ .System }}<|extra_4|>{{ else }}{{ $has_head = false }}{{ end }}
{{ range $index, $message := .Messages }}
{{ if eq $message.Role "user" }}
{{ if and (eq $index 0) $has_head }}{{ $message.Content }}<|extra_0|>{{ else }}<|startoftext|>{{ $message.Content }}<|extra_0|>{{ end }}
{{ else if eq $message.Role "assistant" }}
{{ $message.Content }}
{{ end }}
{{ end }}

{{- range $i, $_ := .Messages }}
{{- $last := eq (len (slice $.Messages $i)) 1 }}
{{- if or (eq .Role "user") (eq .Role "system") }}<start_of_turn>user
{{ .Content }}<end_of_turn>
{{ if $last }}<start_of_turn>model
{{ end }}
{{- else if eq .Role "assistant" }}<start_of_turn>model
{{ .Content }}{{ if not $last }}<end_of_turn>
{{ end }}
{{- end }}
{{- end }}
